191			// Enrich the list result with the detail endpoint, which carries the
192			// rendered description (trail.body_document.text_snapshot) the list
193			// omits, and surface a browser URL. The detail fetch is best-effort:
194			// the core metadata already came from the list, so a detail failure
195			// falls back to the list body with a warning rather than failing.
196			m := found.ToMetadata()
