+		t.Run("rejects "+tc.name, func(t *testing.T) {
+			t.Parallel()
+			if _, err := planTrailBranchChange(t.Context(), tc.found, tc.inputs); err == nil {
+				t.Fatal("expected an error, got nil")
+			}
+		})
+	}
+}
